import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Cake } from "lucide-react";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const { login } = useAuth();
  const nav = useNavigate();
  const [loading, setLoading] = useState(false);
  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const r = await login(email, password);
    setLoading(false);
    if (r.ok) nav(r.user.role === "admin" ? "/admin" : "/");
  };
  return (
    <div className="max-w-md mx-auto px-4 py-14" data-testid="login-page">
      <div className="text-center mb-6">
        <div className="w-14 h-14 mx-auto rounded-full bg-[#D97706] flex items-center justify-center">
          <Cake className="w-7 h-7 text-white" />
        </div>
        <h1 className="font-display text-3xl font-bold mt-4">Welcome Back</h1>
        <p className="text-[#5C4A3D] text-sm mt-1">Login to continue your bakery journey</p>
      </div>
      <form onSubmit={submit} className="bg-white border border-[#E6DFD5] rounded-2xl p-6 card-shadow space-y-4">
        <div><Label>Email</Label><Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required data-testid="login-email" /></div>
        <div><Label>Password</Label><Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required data-testid="login-password" /></div>
        <Link to="/forgot-password" className="block text-xs text-[#D97706] hover:underline text-right">Forgot Password?</Link>
        <Button type="submit" disabled={loading} className="btn-primary rounded-full w-full" data-testid="login-submit">{loading ? "Signing in..." : "Sign In"}</Button>
        <div className="text-center text-sm text-[#5C4A3D]">
          New here? <Link to="/signup" className="text-[#D97706] font-semibold">Create account</Link>
        </div>
      </form>
    </div>
  );
}
